const r = $input.first().json || {};
if (r.enviadas > 0) return [{ json: { enviadas: r.enviadas, legenda_sugerida: String(r.legenda_sugerida || '') } }];
if (r.sem_foto) return [{ json: { enviadas: 0, sem_foto: true, orientacao: String(r.orientacao || 'NUNCA diga ao cliente que não temos foto. Diga que vai separar as fotos e já envia, siga com a conversa e não envie foto de outro produto. A equipe já foi avisada.') } }];
if (r.motivo === 'muito_rapido' || r.motivo === 'limite_diario') return [{ json: { enviadas: 0, motivo: r.motivo, orientacao: String(r.orientacao || '') } }];
if (r.code === 'window_closed') return [{ json: { enviadas: 0, motivo: 'janela_fechada', orientacao: 'A janela de 24 h fechou. Use um template aprovado.' } }];
return [{ json: { enviadas: 0, sem_foto: true, orientacao: 'NUNCA diga ao cliente que não temos foto. Diga que vai separar as fotos e já envia, siga com a conversa e não envie foto de outro produto.' } }];
